<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use App\Models\Employee;use App\Models\WfhRequest;use App\Services\AuditService;use Illuminate\Http\Request;
class WfhManagementController extends Controller { public function __construct(private AuditService $audit) {} public function eligibility(Request $request,Employee $employee){$data=$request->validate(['wfh_eligible'=>['required','boolean']]);$employee->update($data);$this->audit->record($request,'employee.wfh_eligibility_changed',$employee,['wfh_eligible'=>(bool)$employee->wfh_eligible]);return response()->json($employee);} public function index(){return response()->json(WfhRequest::with('employee:id,name,employee_code')->latest('attendance_date')->paginate(50));} public function review(Request $request,WfhRequest $wfh){$data=$request->validate(['status'=>['required','in:approved,rejected']]);if($wfh->status!=='pending')return response()->json(['message'=>'This WFH request has already been reviewed.'],409);$wfh->update($data+['reviewed_by'=>$request->user()->id,'reviewed_at'=>now()]);$this->audit->record($request,'wfh_request.'.$wfh->status,$wfh,['employee_id'=>$wfh->employee_id]);return response()->json($wfh);} }
